import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for square matrix multiplication
square_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void square_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor square_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Define block and grid dimensions
    // For a simple start, use 16x16 threads per block
    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    square_matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    // Synchronize to ensure kernel completion before returning (for debugging/correctness checks)
    // cudaDeviceSynchronize(); 

    return C;
}
"""

square_matmul_cpp_source = (
    "torch::Tensor square_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
square_matmul = load_inline(
    name="square_matmul",
    cpp_sources=square_matmul_cpp_source,
    cuda_sources=square_matmul_source,
    functions=["square_matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()

    def forward(self, A, B):
        return square_matmul.square_matmul_cuda(A, B)

