import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for square matrix multiplication with shared memory and tiling
square_matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size, adjust for performance tuning
#define TILE_SIZE 32

__global__ void square_matmul_kernel_tiled(const float* A, const float* B, float* C, int N) {
    // Block-wide shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    int row = blockRow * TILE_SIZE + threadIdx.y;
    int col = blockCol * TILE_SIZE + threadIdx.x;

    float Cvalue = 0.0f;

    // Loop over all tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles from global memory to shared memory
        int Acol = t * TILE_SIZE + threadIdx.x;
        int Brow = t * TILE_SIZE + threadIdx.y;

        if (row < N && Acol < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + Acol];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside matrix bounds
        }

        if (Brow < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[Brow * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        __syncthreads();

        // Perform matrix multiplication on the shared memory tiles
        for (int k = 0; k < TILE_SIZE; ++k) {
            Cvalue += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}

torch::Tensor square_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch.zeros({N, N}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    square_matmul_kernel_tiled<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

square_matmul_cpp_source = (
    "torch::Tensor square_matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
square_matmul = load_inline(
    name="square_matmul",
    cpp_sources=square_matmul_cpp_source,
    cuda_sources=square_matmul_source,
    functions=["square_matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()

    def forward(self, A, B):
        return square_matmul.square_matmul_cuda(A, B)
